                loss = criterion(outputs, labels)
                val_loss += loss.item()

        val_loss /= len(val_loader)
        experiment_data["multi_dataset_evaluation"][dataset_name]["losses"][
            "val"
        ].append(val_loss)
        print(
            f"{dataset_name} | Epoch {epoch + 1}/{num_epochs}: validation_loss = {val_loss:.4f}, TOE = {TOE:.4f}"
        )

